def partitionEvensOdds (nums : List Nat) (h_precond : partitionEvensOdds_precond (nums)) : (List Nat × List Nat) :=
  nums.foldl (fun (acc : List Nat × List Nat) n =>
    if n % 2 == 0 then (n :: acc.fst, acc.snd) else (acc.fst, n :: acc.snd))
    (List.nil, List.nil) |>.swap
